/**
 * SNAKE 3D: Cyber Grid - Level Layout Database
 * Contains procedural mathematical routines to reconstruct grid configurations.
 */

function initSectorConfig2() {
    const size = 21;
    const obstacles = [];
    const edgeLimit = Math.floor(size / 2) - 3;
    for (let x = -edgeLimit; x <= edgeLimit; x++) {
        if (x !== 0 && Math.abs(x) > 2) {
            obstacles.push({ x: x, y: 0, z: 2 });
            obstacles.push({ x: x, y: 0, z: -2 });
        }
    }
    return {
        id: 2,
        name: "Chronos Core Sector",
        gridSize: size,
        tickSpeed: 84,
        targetScore: 5000,
        theme: {
            clearColor: 0x030306,
            fogColor: 0x030306,
            fogNear: 15,
            fogFar: 50,
            gridColor: 0x9d00ff,
            wallColor: 0x111122,
            wallEmissive: 0x050511,
            ambientLight: 0x111122,
            spotLight: 0x9d00ff,
            particleColor: 0x9d00ff
        },
        obstacles: obstacles
    };
}

